package domain

import (
	"encoding/json"
	"os"
	"reflect"
	"strings"
	"testing"
	"time"
)

// These tests hold the Go port of the shared rules to the TypeScript original: testdata/golden.json is generated by
// running @ecom/contracts (see testdata/gen/gen.mjs) over hundreds of carts, coupons, amounts and products, and the
// Go results must match it exactly.

type golden struct {
	Now       string `json:"now"`
	CartCases []struct {
		Stored    StoredCart                 `json:"stored"`
		Overrides map[string]json.RawMessage `json:"overrides"`
		Expected  struct {
			Cart   json.RawMessage `json:"cart"`
			Stored json.RawMessage `json:"stored"`
		} `json:"expected"`
	} `json:"cartCases"`
	Coupons []struct {
		Code     string `json:"code"`
		Subtotal int64  `json:"subtotal"`
		Expected struct {
			OK       bool            `json:"ok"`
			Coupon   json.RawMessage `json:"coupon"`
			Discount int64           `json:"discount"`
			Message  string          `json:"message"`
		} `json:"expected"`
	} `json:"coupons"`
	Shipping []struct {
		Method   string `json:"method"`
		Amt      int64  `json:"amt"`
		Free     bool   `json:"free"`
		Expected int64  `json:"expected"`
	} `json:"shipping"`
	Money []struct {
		Amount   int64  `json:"amount"`
		Expected string `json:"expected"`
	} `json:"money"`
	Pincodes []struct {
		Pincode  string          `json:"pincode"`
		Expected json.RawMessage `json:"expected"`
	} `json:"pincodes"`
	COD []struct {
		Pincode  string `json:"pincode"`
		Total    int64  `json:"total"`
		Expected struct {
			Enabled bool   `json:"enabled"`
			Reason  string `json:"reason"`
		} `json:"expected"`
	} `json:"cod"`
	Passwords []struct {
		Password string  `json:"password"`
		Expected *string `json:"expected"`
	} `json:"passwords"`
	Permissions []struct {
		Roles    []Role   `json:"roles"`
		Expected []string `json:"expected"`
	} `json:"permissions"`
	Summaries []struct {
		ID       string          `json:"id"`
		Expected json.RawMessage `json:"expected"`
	} `json:"summaries"`
	Sorts []struct {
		Sort     string   `json:"sort"`
		Expected []string `json:"expected"`
	} `json:"sorts"`
	Stock []struct {
		ID       string `json:"id"`
		Discount int    `json:"discount"`
		Expected struct {
			Status StockStatus `json:"status"`
			Left   *int64      `json:"left"`
		} `json:"expected"`
	} `json:"stock"`
}

func loadGolden(t *testing.T) (*golden, []Product) {
	t.Helper()
	var g golden
	raw, err := os.ReadFile("../../testdata/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatal(err)
	}
	var products []Product
	raw, err = os.ReadFile("../../testdata/products.json")
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(raw, &products); err != nil {
		t.Fatal(err)
	}
	return &g, products
}

// sameJSON compares a Go value with expected JSON structurally (so key order and number formatting do not matter).
func sameJSON(t *testing.T, name string, got any, want json.RawMessage) {
	t.Helper()
	gb, err := json.Marshal(got)
	if err != nil {
		t.Fatalf("%s: %v", name, err)
	}
	var g, w any
	_ = json.Unmarshal(gb, &g)
	_ = json.Unmarshal(want, &w)
	if !reflect.DeepEqual(g, w) {
		t.Errorf("%s differs\n got: %s\nwant: %s", name, gb, want)
	}
}

func TestPriceCartMatchesTypeScript(t *testing.T) {
	g, products := loadGolden(t)
	now, _ := time.Parse(time.RFC3339, g.Now)
	for i, c := range g.CartCases {
		patched := make([]Product, len(products))
		for pi, p := range products {
			cp := p
			cp.Variants = append([]Variant(nil), p.Variants...)
			for vi := range cp.Variants {
				if raw, ok := c.Overrides[cp.Variants[vi].ID]; ok {
					var o struct {
						Stock     *int64     `json:"stock"`
						Backorder *Backorder `json:"backorder"`
					}
					_ = json.Unmarshal(raw, &o)
					if o.Stock != nil {
						cp.Variants[vi].Stock = *o.Stock
					}
					if o.Backorder != nil {
						cp.Variants[vi].Backorder = o.Backorder
					}
				}
			}
			patched[pi] = cp
		}
		got := PriceCart(c.Stored, patched, now)
		sameJSON(t, "cart #"+itoa(i), got.Cart, c.Expected.Cart)
		sameJSON(t, "stored #"+itoa(i), got.Stored, c.Expected.Stored)
		if t.Failed() {
			return
		}
	}
}

func itoa(i int) string { b, _ := json.Marshal(i); return string(b) }

func TestCouponsMatchTypeScript(t *testing.T) {
	g, _ := loadGolden(t)
	now, _ := time.Parse(time.RFC3339, g.Now)
	for _, c := range g.Coupons {
		got := EvaluateCoupon(c.Code, c.Subtotal, now)
		if got.OK != c.Expected.OK || got.Discount != c.Expected.Discount || got.Message != c.Expected.Message {
			t.Errorf("coupon %q on %d: got ok=%v discount=%d %q, want ok=%v discount=%d %q", c.Code, c.Subtotal, got.OK, got.Discount, got.Message, c.Expected.OK, c.Expected.Discount, c.Expected.Message)
		}
	}
}

func TestShippingMatchesTypeScript(t *testing.T) {
	g, _ := loadGolden(t)
	for _, c := range g.Shipping {
		if got := ShippingFee(ShippingMethodID(c.Method), c.Amt, c.Free); got != c.Expected {
			t.Errorf("shipping %s %d free=%v: got %d want %d", c.Method, c.Amt, c.Free, got, c.Expected)
		}
	}
}

func TestMoneyFormattingMatchesTypeScript(t *testing.T) {
	g, _ := loadGolden(t)
	for _, c := range g.Money {
		// Node's ICU renders the rupee amounts with a non-breaking space in some locales; compare ignoring it.
		want := strings.ReplaceAll(c.Expected, " ", " ")
		if got := FormatMoney(INRInt(c.Amount)); got != want {
			t.Errorf("FormatMoney(%d) = %q, want %q", c.Amount, got, want)
		}
	}
}

func TestServiceabilityAndCODMatchTypeScript(t *testing.T) {
	g, _ := loadGolden(t)
	now, _ := time.Parse(time.RFC3339, g.Now)
	for _, c := range g.Pincodes {
		sameJSON(t, "serviceability "+c.Pincode, ComputeServiceability(c.Pincode, now), c.Expected)
	}
	for _, c := range g.COD {
		enabled, reason := CODEligibility(c.Pincode, c.Total)
		if enabled != c.Expected.Enabled || reason != c.Expected.Reason {
			t.Errorf("cod %s %d: got %v %q want %v %q", c.Pincode, c.Total, enabled, reason, c.Expected.Enabled, c.Expected.Reason)
		}
	}
}

func TestPasswordsAndPermissionsMatchTypeScript(t *testing.T) {
	g, _ := loadGolden(t)
	for _, c := range g.Passwords {
		want := ""
		if c.Expected != nil {
			want = *c.Expected
		}
		if got := PasswordProblem(c.Password); got != want {
			t.Errorf("PasswordProblem(%q) = %q, want %q", c.Password, got, want)
		}
	}
	for _, c := range g.Permissions {
		if got := PermissionsFor(c.Roles); !reflect.DeepEqual(got, c.Expected) {
			t.Errorf("PermissionsFor(%v) = %v, want %v", c.Roles, got, c.Expected)
		}
	}
}

func TestCatalogDerivationsMatchTypeScript(t *testing.T) {
	g, products := loadGolden(t)
	byID := map[string]*Product{}
	for i := range products {
		byID[products[i].ID] = &products[i]
	}
	for _, c := range g.Summaries {
		sameJSON(t, "summary "+c.ID, ToSummary(byID[c.ID]), c.Expected)
	}
	for _, c := range g.Stock {
		status, left := StockStatusOf(byID[c.ID])
		if status != c.Expected.Status || (left == nil) != (c.Expected.Left == nil) || (left != nil && *left != *c.Expected.Left) || BestDiscount(byID[c.ID]) != c.Discount {
			t.Errorf("stock/discount for %s differ: got %v %v %d", c.ID, status, left, BestDiscount(byID[c.ID]))
		}
	}
	for _, c := range g.Sorts {
		sorted := SortProducts(products, SortKey(c.Sort), nil)
		ids := make([]string, len(sorted))
		for i := range sorted {
			ids[i] = sorted[i].ID
		}
		if !reflect.DeepEqual(ids, c.Expected) {
			t.Errorf("sort %s differs (first got %v, want %v)", c.Sort, ids[:min(5, len(ids))], c.Expected[:min(5, len(c.Expected))])
		}
	}
}
